mapper.select:
SELECT m.id AS matchId, m.user_id AS userId, m.title, m.price, m.status, m.match_type AS matchType, m.created_at AS createdAt FROM `match` m WHERE m.deleted = 1
AND m.user_id = #{userId}
ORDER BY m.id DESC LIMIT #{size} OFFSET #{offset}

mapper.update:
UPDATE `match`
SET status = #{status}
WHERE id = #{matchId}
  AND deleted = 1
